import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions_default():
    @click.command()
    def cli_raises():
        raise ValueError("This is an error")

    runner = CliRunner()
    result = runner.invoke(cli_raises)
    assert result.exception is not None
    assert isinstance(result.exception, ValueError)

def test_runner_catch_exceptions_false_on_runner():
    @click.command()
    def cli_raises():
        raise ValueError("This is an error")

    runner = CliRunner(catch_exceptions=False)
    with pytest.raises(ValueError, match="This is an error"):
        runner.invoke(cli_raises)

def test_runner_catch_exceptions_override_on_invoke():
    @click.command()
    def cli_raises():
        raise ValueError("This is an error")

    runner = CliRunner(catch_exceptions=True)
    with pytest.raises(ValueError, match="This is an error"):
        runner.invoke(cli_raises, catch_exceptions=False)

import pytest
import click


class MyClass:
    def __init__(self, myvalue: str) -> None:
        self.myvalue = myvalue

    @staticmethod
    def from_str(input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str!r}, should be 'works'")
        return MyClass(input_str)


@click.command()
@click.argument("mydata", type=click.types.FuncParamType(MyClass.from_str))
def cli(mydata: MyClass) -> None:
    click.echo(f"MyClass value: {mydata.myvalue}")


def test_func_param_type_value_error_message(runner):
    """
    Test that FuncParamType uses the ValueError message when conversion fails.
    """
    result = runner.invoke(cli, ["fails"])
    assert result.exit_code == 2
    assert "Error: Invalid value for 'MYDATA': input was 'fails', should be 'works'" in result.output

